"tokyo|Harry Potter Cafe":{"t": "احجز قبل، الويكند يمتلي", "cost": "الغداء ~¥3k، العشاء ~¥5k", "dur": "80–100 دقيقة", "cap": "إكسبكتو باترونوم!", "tip": "لو تحب هاري بوتر، هذا المقهى لازم تروح له، كله على طابع الفلم. في الدور الأرضي من Akasaka Biz Tower، قدام مخرج 3 من محطة أكاساكا على طول. احجز من hpcafe.jp، والحد 4 أشخاص. اطلب كعكة هيدويغ. انتبه: باب الشارع المزيّف ديكور بس، ادخل من لوبي البرج."},
"tokyo|Pokemon Cafe":{"t": "احجز قبل 31 يوم", "cost": "~¥3,300 (وجبة + مشروب)", "dur": "1.5 ساعة", "cap": "لاتيه بيكاتشو، يجنن", "tip": "مقهى بوكيمون اللي الكل يبيه، في الدور الخامس من نيهونباشي تاكاشيمايا. الحجز يفتح الساعة 6 المغرب بتوقيت اليابان قبل 31 يوم، ويخلص في ثواني، فخلك جاهز بدري. ما عندك حجز؟ جرّب طابور الحضور المباشر، يمكن تلحق مقعد أحد كنسل."},
"tokyo|Moses Kebab":{"t": "آخر الليل", "cost": "¥600–1,350", "dur": "15 دقيقة", "cap": "الكباب الكبير!", "tip": "كباب حلال يسدّ جوعك آخر الليل، كشك جنب محطة أكيهابارا. اطلب Big Kebab باللحم البقري مع لحم زيادة، يجيك في خبز دائري ضخم."},
"tokyo|Nana's Green Tea":{"t": "العصر", "dur": "45 دقيقة", "cap": "ماتشا بكل شي", "tip": "لو تحب الماتشا، هذا مكانك. سلسلة مقاهي بدأت في جييوغاوكا: لاتيه ماتشا، وبارفيه ماتشا، وأطباق رز يابانية. لها فرع في أغلب المحطات الكبيرة، روح لأقرب واحد لك."},
"kyoto|Koé Donuts":{"t": "الصبح، قبل الطابور", "dur": "30 دقيقة", "cap": "قبة خيزران فوق الدونات", "tip": "دونات عضوية في مكان تصميمه يفتح النفس، صممه المعماري كينغو كوما في شينكيوغوكو، والسقف من 572 سلة خيزران منسوجة. شوفهم وهم يسوّونها، وبعدها خذ وحدة بماتشا كيوتو."},
"kyoto|Shamisen Dojo":{"t": "احجز قبل", "cost": "~$95", "dur": "1.5 ساعة", "cap": "صرت عازف شاميسن!", "tip": "تجربة يابانية أصيلة: تتعلم تعزف على الشاميسن مع مدرّب محترف في موراساكينو. تلبس زي الساموي، ويقدّمون لك شاي أخضر في الاستراحة، والمعلّم يعزف لك بنفسه، وتطلع معك صور وفيديوهات."},
