"tokyo|Final Fantasy Eorzea Cafe":{"t": "10:45 الصبح–11 بالليل، فترات 90 دقيقة", "cost": "~¥2,000–3,500", "dur": "1.5 ساعة", "cap": "FF14 مثل ما يبي القلب", "tip": "لو أنت من جماعة FFXIV، هذا الكافيه الرسمي ولازم تمر. في الدور الثاني من Pasela Akiba، أطباق مستوحاة من اللعبة ومنتجات كثير بتشتريها وأنت ما كنت ناوي. الفترات محددة 90 دقيقة، وتنحجز أونلاين الساعة 12 الظهر بالضبط قبل شهر كامل، وبدون حجز بس لو فيه كرسي فاضي. فيه كحول بقائمة المشروبات، فاطلب من قسم المشروبات الغازية والعصيرات."},
"tokyo|Morinoen":{"t": "المحل 9–7، والكوفي 12–6 المغرب", "cost": "~¥500–1,000", "dur": "40 دقيقة", "cap": "آيس كريم هوجيتشا", "tip": "تشم ريحة المحل قبل لا تشوفه، يحمصون شاي الهوجيتشا عندهم بالمحل من 1914. ثلاثين ثانية من مخرج A1 في نينغيوتشو. خذ الآيس كريم الطري بالشاي المحمص من الدور اللي تحت حتى لو ما دخلت الكوفي."},
"tokyo|Owl Nest Cafe":{"t": "أيام الأسبوع 1–7 المغرب، والويكند 12–8 بالليل", "cost": "~¥1,000 للساعة مع مشروب", "dur": "1 ساعة", "cap": "بومة على كتفك", "tip": "ساعة مع البوم ومعها مشروب واحد، و¥500 زيادة لو تبي تأكلهم. اللي جربوه دايم يقولون إن الطيور هنا شكلها بخير وتطير براحتها، بس كافيهات البوم موضوع عليه جدل، فروح وأنت فاهم هالشي أو تخطاه."},
"tokyo|Hekkelun":{"t": "9 الصبح–3 العصر، الاثنين/الثلاثاء/الخميس/الجمعة بس", "cost": "~¥900", "dur": "40 دقيقة", "cap": "12 بودينغ باليوم وبس", "tip": "كيساتين قديم من زمن شووا، صاحبه يسوي اثنعش بودينغ كراميل بالضبط كل يوم. الطابور يبدأ تقريبًا 8 الصبح وتخلص قبل الظهر، فهذي خطة للي يصحى بدري. مسكر الأربعاء والسبت والأحد، والتدخين مسموح داخل."},
