"osaka|Namba Yasaka Shrine":{"t": "6 الصبح–5 العصر", "cost": "ببلاش", "dur": "20 دقيقة", "cap": "راس الأسد العملاق", "tip": "شراين صغير فيه مسرح على شكل راس أسد طوله 12 متر، فاتح فمه، يقولون إنه يبلع الحظ السيء. من أغرب وأحلى اللقطات في أوساكا. عشر دقايق مشي من نامبا."},
"osaka|Kuromon Market":{"t": "~9 الصبح–5 العصر", "cost": "تذوّق ¥500–3,000+", "dur": "1 ساعة", "cap": "مطبخ أوساكا", "tip": "سوق مسقوف طوله 600 متر، فيه مأكولات بحرية وفواكه وأكل شارع على أعواد. صار سياحي وغالي، بس لسا وناسة تتذوق فيه. المأكولات البحرية والفواكه هي الخيار الآمن. أسياخ الواغيو مو حلال."},
"osaka|Den Den Town":{"t": "~11 الصبح–8 بالليل", "cost": "المشي ببلاش", "dur": "1.5 ساعة", "cap": "أكيهابارا أوساكا", "tip": "شارع الأنمي والإلكترونيات في أوساكا: فيقرات، مانغا، ألعاب ريترو وأجهزة قديمة، وزحمته أقل من أكيهابارا. عشر دقايق مشي جنوب نامبا."},
"osaka|Shinsekai":{"t": "أحلى وقت المغرب", "cost": "المشي ببلاش", "dur": "1 ساعة", "cap": "نيون وأوساكا القديمة", "tip": "حي ريترو من العشرينات، لوحات نيون، وفوانيس سمك منفوخ ضخمة، وبرج تسوتينكاكو بالنص. أغلب الأكل كوشيكاتسو، مقلي على أعواد وغالبًا خنزير، والبيرة بكل مكان، فتعال عشان الشكل وكل بمكان ثاني. افرك رجول تمثال Billiken للحظ."},
"osaka|Tsutenkaku":{"t": "10 الصبح–8 بالليل", "cost": "المنصة ~¥1,000–1,500، الزحليقة زيادة", "dur": "45 دقيقة", "cap": "البرج اللي فيه زحليقة", "tip": "البرج الحديد القديم بنص شينسيكاي. الوناسة في Tower Slider: زحليقة أنبوب طولها 60 متر تنزل من برا البرج، تقريبًا ¥1,000 زيادة. المنظر عادي، الزحليقة هي السبب تروح."},
"osaka|Tennoji Park & Zoo":{"t": "حديقة الحيوان 9:30 الصبح–5 العصر، مسكرة الاثنين", "cost": "الحديقة ببلاش، حديقة الحيوان ~¥500", "dur": "2 ساعة", "cap": "عصرية رايقة مع البزارين", "tip": "عشب كبير فيه كافيهات وألعاب أطفال تحت أبينو هاروكاس على طول، وجنبه حديقة حيوان قديمة. رخيص وسهل وحلو مع البزارين. وشينسيكاي خمس دقايق مشي."},
"osaka|Grand Green Osaka":{"t": "مفتوحة طول اليوم", "cost": "ببلاش", "dur": "45 دقيقة", "cap": "حديقة جنب المحطة", "tip": "حديقة جديدة جنب محطة أوساكا على طول، فيها عشب كبير ونوافير ومباني جديدة حولها. حلوة مرة لاستراحة بين القطارات أو بكنك مع البزارين. لسا تكبر، وبيفتح فيها أكثر بالسنين الجاية."},
