"osaka|Nakazakicho":{"t": "~12 الظهر–6 المغرب", "cost": "المشي ببلاش", "dur": "1.5 ساعة", "cap": "بيوت قديمة وكافيهات جديدة", "tip": "حي صغير فيه بيوت خشب قديمة نجت من الحرب، والحين مليانة كافيهات صغيرة ومحلات فينتج واستوديوهات. مشوار هادي ورايق، محطة وحدة بس من زحمة أوميدا."},
"osaka|Tenjinbashisuji Shopping Street":{"t": "~10 الصبح–8 بالليل", "cost": "المشي ببلاش", "dur": "1–2 ساعة", "cap": "أطول شارع تسوق في اليابان", "tip": "أطول شارع تسوق مسقوف في اليابان، تقريبًا 2.6 كم على خط واحد. سناكات رخيصة ومحلات محلية وحياة أوساكا الحقيقية، مو محلات سياح. امشِ جزء منه، ومسقوف فالمطر ما يفرق."},
"osaka|Osaka Museum of Housing and Living":{"t": "10 الصبح–5 العصر، مسكر الثلاثاء", "cost": "~¥600", "dur": "1–1.5 ساعة", "cap": "شارع إيدو كامل داخل مبنى", "tip": "شارع أوساكا كامل من حوالي سنة 1830، مبني داخل مبنى بالحجم الحقيقي، فيه محلات وبيوت تدخلها، والإضاءة تتغير من نهار لليل. تقدر تستأجر يوكاتا وتتمشى فيه. البزارين يحبونه."},
"osaka|Kema Sakuranomiya Park":{"t": "مفتوحة طول اليوم", "cost": "ببلاش", "dur": "1 ساعة", "cap": "4 كم ساكورا", "tip": "حديقة على النهر فيها آلاف أشجار الساكورا على امتداد نهر أوكاوا. أول أبريل تصير نفق وردي طويل. وبرا الموسم مشوار حلو على النهر."},
"osaka|Nakanoshima Museum of Art":{"t": "10 الصبح–5 العصر، مسكر الاثنين", "cost": "حسب المعرض", "dur": "1.5 ساعة", "cap": "المكعب الأسود", "tip": "متحف فن حديث في مبنى مكعب أسود لافت على جزيرة ناكانوشيما. معارض كبيرة تتغير، من التصميم للمانغا. تمثال القطو الضخم اللي برا هو اللقطة. شيّك وش المعروض قبل تروح."},
"osaka|Osaka Aquarium Kaiyukan":{"t": "10 الصبح–8 بالليل", "cost": "~¥2,700–3,200، حسب التاريخ", "dur": "2–3 ساعات", "cap": "القرش الحوتي", "tip": "من أكبر الأكواريومات في العالم. تنزل بممر حلزوني حول حوض واحد ضخم فيه قرش حوتي. الأسعار تتغير حسب التاريخ، فاشترِ أونلاين. حلو مرة مع البزارين."},
"osaka|Tempozan Ferris Wheel":{"t": "10 الصبح–9 بالليل", "cost": "~¥1,000", "dur": "15 دقيقة", "cap": "الخليج من فوق", "tip": "عجلة دوّارة طولها 112 متر جنب الأكواريوم على طول، تطل على خليج أوساكا. لو قلبك قوي اطلب الكابينة الشفافة. تنوّر بألوان بالليل."},
"osaka|Santa Maria Cruise":{"t": "رحلات نهار وغروب، شيّك الأيام", "cost": "~¥2,000 (الغروب ~¥2,300)", "dur": "45 دقيقة", "cap": "سفينة حول الخليج", "tip": "نسخة من سفينة كولومبوس، تلف بخليج أوساكا تقريبًا 45 دقيقة، وتطلع من جنب الأكواريوم. رحلة الغروب هي الأحلى. داخلة في Osaka Amazing Pass."},
"nara|Kasuga Taisha":{"t": "~6:30 الصبح–5:30 العصر", "cost": "الساحة ببلاش، الداخل ~¥700", "dur": "1 ساعة", "cap": "3,000 فانوس", "tip": "الشراين الكبير في نارا، بآخر ممر غابة على جوانبه تقريبًا 3,000 فانوس حجر وبرونز، والغزلان تمشي بينها. الفوانيس كلها ما تنوّر إلا مرتين بالسنة، في فبراير ونص أغسطس. 20 دقيقة مشي بالحديقة من تودايجي."},
"nara|Kasugayama Primeval Forest":{"t": "وقت النهار", "cost": "ببلاش", "dur": "1.5–2 ساعة", "cap": "غابة ما أحد قطعها", "tip": "غابة قديمة ورا كاسوغا تايشا، ما انقطع منها شي من أكثر من ألف سنة. ممشى هادي بين أشجار قديمة ضخمة، وغالبًا ما فيه أحد غيرك. خذ مويه وجزمة مريحة."},
"nara|Kofuku-ji":{"t": "الساحة مفتوحة طول اليوم، المتحف 9 الصبح–5 العصر", "cost": "الساحة ببلاش، المتحف ~¥700", "dur": "45 دقيقة", "cap": "التمثال أبو ست أيادي", "tip": "من أقدم تمبلات نارا، على طرف الحديقة على طول. الباغودا المشهورة أم خمس طوابق مغطاة بسقالات لتصليح كبير لين تقريبًا 2031. ادخل متحف الكنوز وشوف تمثال Ashura أبو ثلاث وجيه وست أيادي."},
"nara|Nara National Museum":{"t": "9:30 الصبح–5 العصر، مسكر الاثنين", "cost": "~¥700", "dur": "1.5 ساعة", "cap": "كنوز بوذية", "tip": "أحسن مجموعة تماثيل وفن بوذي في اليابان، داخل حديقة نارا. بآخر الخريف يسوون معرض كنوز Shosoin المشهور، والطوابير فيه طويلة مرة. استراحة حلوة من الغزلان."},
"nara|Isuien Garden":{"t": "9:30 الصبح–4:30 العصر، مسكرة الثلاثاء", "cost": "~¥1,200", "dur": "45 دقيقة", "cap": "جبال مستعارة", "tip": "حديقة حلوة مرة من زمن ميجي، خلفيتها بوابة تودايجي الكبيرة والتلال اللي وراها. بحيرات وحجار تمشي عليها وبيت شاي. هادية حتى لو الحديقة اللي برا زحمة."},
"nara|Yoshikien Garden":{"t": "9 الصبح–5 العصر", "cost": "ببلاش للسياح الأجانب (وريهم الجواز)", "dur": "30 دقيقة", "cap": "الحديقة المجانية", "tip": "جنب إيسوين على طول: ثلاث حدائق صغيرة، طحالب وبحيرة وحديقة شاي. ببلاش للسياح الأجانب لو معك جوازك. من أهدى زوايا نارا."},
"nara|Mount Wakakusa":{"t": "من نص مارس لين نص ديسمبر", "cost": "~¥150", "dur": "1–1.5 ساعة", "cap": "الغروب على نارا", "tip": "تلة عشب ورا حديقة نارا. طلعة 30–40 دقيقة، وفوق فيه غزلان، وتشوف المدينة كلها. روح وقت الغروب. مفتوحة من نص مارس لين نص ديسمبر."},
"nara|Naramachi":{"t": "~10 الصبح–5 العصر", "cost": "المشي ببلاش", "dur": "1–1.5 ساعة", "cap": "أزقة التجار القديمة", "tip": "أزقة ضيقة فيها بيوت تجار خشب قديمة، صارت الحين كافيهات صغيرة ومحلات حلويات وحِرف. مشوار هادي بعيد عن زحمة الغزلان، كم دقيقة جنوب بحيرة ساروساوا."},
