"nara|Higashimuki Shopping Street":{"t": "~10 الصبح–8 بالليل", "cost": "المشي ببلاش", "dur": "30 دقيقة", "cap": "من المحطة للحديقة", "tip": "شارع تسوق مسقوف يمشي من محطة Kintetsu Nara لجهة الحديقة. هدايا، وسناكات على شكل غزلان، وأكل رخيص. ودق الموتشي السريع حق Nakatanidou عند اللفة على طول."},
"nara|Sarusawa Pond":{"t": "أي وقت", "cost": "ببلاش", "dur": "15 دقيقة", "cap": "البحيرة جنب الباغودا", "tip": "بحيرة صغيرة على طرف حديقة نارا. اللقطة الكلاسيكية انعكاس باغودا كوفوكوجي بالمويه، بس الباغودا مغطاة بسقالات لين تقريبًا 2031. لسا وقفة حلوة بين المحطة وناراماتشي."},
"nara|Heijo Palace Site":{"t": "9 الصبح–4:30 العصر، مسكر الاثنين", "cost": "ببلاش", "dur": "1.5 ساعة", "cap": "عاصمة نارا الضايعة", "tip": "أرض القصر الإمبراطوري من القرن الثامن: ساحة مفتوحة ضخمة فيها قاعة عرش مبنية من جديد وبوابة حمرا عملاقة. ببلاش وهادي. استأجر سيكل، المكان كبير."},
