"nara|Horyu-ji":{"t": "8 الصبح–5 العصر (4:30 بالشتا)", "cost": "~¥1,500–2,000", "dur": "1.5–2 ساعة", "cap": "أقدم مباني خشب", "tip": "أقدم مباني خشب في العالم، واقفة من تقريبًا 1,300 سنة. مجمع تمبلات كبير وهادي فيه باغودات وقاعات كنوز. تقريبًا 30 دقيقة من نارا بقطار JR وبعدها باص قصير أو مشي."},
"nara|Hase-dera (Sakurai)":{"t": "8:30 الصبح–5 العصر", "cost": "~¥500", "dur": "1.5 ساعة", "cap": "الدرج المسقوف", "tip": "تمبل بالجبل فيه درج مسقوف طويل، 399 درجة، يوصلك لمنصة خشب فوق الوادي. فاوانيا آخر أبريل، وهيدرانجيا في يونيو، وأوراق حمرا بالخريف. تقريبًا ساعة من نارا على خط Kintetsu. مو نفس هاسيديرا اللي في كاماكورا."},
"nara|Mount Yoshino":{"t": "أحلى وقت أول–نص أبريل", "cost": "ببلاش", "dur": "يوم كامل", "cap": "30,000 شجرة ساكورا", "tip": "جبل كامل مغطى بتقريبًا 30,000 شجرة ساكورا، تفتّح على دفعات من تحت لفوق في أبريل. أشهر جبل ساكورا في اليابان، وزحمة مرة وقت الذروة. تقريبًا ساعة ونص من أوساكا على خط Kintetsu."},
