"kamakura|Dankazura":{"t": "مفتوح طول اليوم", "cost": "ببلاش", "dur": "15 دقيقة", "cap": "ممر الساكورا", "tip": "ممر مرتفع بنص الشارع رايح لتسوروغاوكا هاتشيمانغو، على جوانبه ساكورا ويمر تحت بوابات توري كبيرة. أول أبريل يصير نفق وردي. أهدى من كوماتشي-دوري اللي جنبه."},
"kamakura|Kamakura Museum of National Treasures":{"t": "9 الصبح–4:30 العصر، مسكر الاثنين", "cost": "~¥400–700", "dur": "45 دقيقة", "cap": "تماثيل كاماكورا", "tip": "متحف صغير داخل ساحة الشراين، فيه التماثيل البوذية وكنوز تمبلات كاماكورا. وقفة حلوة لساعة مطر جنب تسوروغاوكا هاتشيمانغو على طول."},
