"kamakura|Enoden Railway":{"t": "كل ~12 دقيقة", "cost": "تذكرة اليوم ~¥800", "dur": "34 دقيقة من أوله لآخره", "cap": "قطار البحر", "tip": "قطار أخضر صغير من سنة 1902، يمشي بين كاماكورا وفوجيساوا، يتدسس بين البيوت وعلى البحر. خذ تذكرة اليوم Noriorikun وانزل في هاسيه وكاماكوراكوكوماي وإنوشيما."},
"kamakura|Enoshima":{"t": "مفتوحة طول اليوم", "cost": "المشي ببلاش", "dur": "نص يوم", "cap": "الجزيرة وقت الغروب", "tip": "جزيرة صغيرة متصلة بالبر بجسر، فيها شراينات وقطاوة وأزقة طالعة ومنحدرات. اطلع بالسلالم الكهربائية الخارجية لو تعبت رجولك. اقعد لين الغروب، فوجي كثير يطلع ورا البحر."},
