"Kobe":{"n": "كوبي", "best": "أحلى يوم أكل حلال في اليابان: لحم كوبي حلال وأقدم مسجد في اليابان.", "go": "قطار JR Special Rapid من أوساكا (20 دقيقة) أو كيوتو (50 دقيقة) إلى سانوميا", "time": "20–50 دقيقة", "cost": "¥410–1,110", "ps": "تذكرة JR Kansai ليوم واحد (¥2,800) ما تستاهل إلا إذا بتضيف هيميجي بنفس اليوم.", "day": "يوم كامل · اطلع قبل 9:30", "see": ["مسجد كوبي (1935)", "بيوت كيتانو إيجينكان", "حديقة ميريكن وهاربورلاند", "تلفريك حديقة نونوبيكي للأعشاب", "منظر جبل روكو بالليل"], "halal": "احجز غدا لحم كوبي حلال (Kobe Beef Steak Sakura، أو Misono، أو Tsuki Usagi)، أو كل حول المسجد في Kobe Shawarma أو Naan Inn أو Ali's Halal Kitchen. لا تاكل من أكل الشارع في الحي الصيني، أغلبه خنزير.", "tip": "روح يوم الجمعة وصلّ الجمعة في المسجد، 15 دقيقة مشي طالع من سانوميا، وبعدها غدا واغيو حلال."},
"Himeji Castle":{"n": "قلعة هيميجي", "best": "أحلى قلعة أصلية في اليابان، بيضاء تلمع فوق التل.", "go": "قطار JR Special Rapid من أوساكا (ساعة) أو كيوتو (ساعة و30 دقيقة)، أو الشينكانسن بنص الوقت", "time": "1–1.5 ساعة", "cost": "¥1,520–2,310", "ps": "من كيوتو، تذكرة JR Kansai Area ليوم واحد (¥2,800) أوفر من الذهاب والرجعة. دخول القلعة ¥2,500 للزوار من مارس 2026.", "day": "نص يوم · اطلع قبل 8:00", "see": ["البرج الرئيسي الخشبي الأصلي", "ممر نيشي-نو-مارو", "حدائق كوكو-إن", "إطلالة شارع أوتيماي-دوري من المحطة", "جبل شوشا (تمبل فيلم The Last Samurai)"], "halal": "ما فيه مطعم حلال موثّق، فكل في كوبي أو أوساكا. فيه مصلى مجاني مع وضوء في Harima Cycle Station، برا محطة JR هيميجي على طول.", "tip": "خلك هناك أول ما يفتح الساعة 9:00. داخل البرج تشيل جزمتك بيدك وتطلع درج قوي، والطابور يكبر بسرعة."},
